using System;
using UnityEngine;

namespace Astrea.GameStates;

public class BattleActionCastStatesAction : Action
{
	protected System.Action noValidRaycastMouseInputAction => delegate
	{
		base.actionInstance.StopFollowingMouse();
		Debug.Log("TARGETSELECTING: Invalid Target");
	};

	protected bool beforeRaycastCheck => base.actionInstance != null;

	public override void Execute(float d)
	{
	}

	protected void CastAction(Action<GameObject> castAction, Action<GameObject> nonValueCastAction, GameObject target = null)
	{
		ActionFace actionFace = base.actionInstance.ActionFace;
		GameObject actionOwner = base.actionInstance.ActionOwner;
		BeforeActionCasted();
		if (actionFace.ActionValue == EffectsValues.NO_VALUE)
		{
			nonValueCastAction(actionOwner);
		}
		else
		{
			castAction(actionOwner);
		}
		if (actionFace.EnableSecondAction)
		{
			actionFace.SecondBattleAction.DiceSecondActionLogic.OnDrop(actionFace, target, actionOwner);
		}
		ActionCasted();
	}
}
